theorem Std.ExtTreeSet.isSome_min?_of_isSome_min?_erase.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} (hs : (t.erase k).min?.isSome = true) :
  t.min?.isSome = true

theorem Std.ExtTreeSet.get?_eq_some_of_contains.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {k : α}
  (h' : t.contains k = true) : t.get? k = some k

theorem Std.ExtTreeSet.get_union_of_mem_right.{u} {α : Type u} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} (mem : k ∈ t₂) :
  (t₁ ∪ t₂).get k ⋯ = t₂.get k mem

theorem Std.ExtTreeSet.mem_filter.{u} {α : Type u} {cmp : α → α → Ordering} {t : Std.ExtTreeSet α cmp}
  [Std.TransCmp cmp] {f : α → Bool} {k : α} :
  k ∈ Std.ExtTreeSet.filter f t ↔ ∃ (h : k ∈ t), f (t.get k h) = true

theorem Std.ExtTreeSet.getD_eq_getD_get?.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {a fallback : α} :
  t.getD a fallback = (t.get? a).getD fallback

theorem Std.ExtTreeSet.maxD_erase_le_maxD.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} (he : t.erase k ≠ ∅) {fallback : α} :
  (cmp ((t.erase k).maxD fallback) (t.maxD fallback)).isLE = true

theorem Std.ExtTreeSet.self_le_max?_insert.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k kmi : α} (hkmi : (t.insert k).max?.get ⋯ = kmi) :
  (cmp k kmi).isLE = true

theorem Std.ExtTreeSet.min!_eq_iff_mem_and_forall.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] [Inhabited α] (he : t ≠ ∅)
  {km : α} : t.min! = km ↔ km ∈ t ∧ ∀ k ∈ t, (cmp km k).isLE = true

theorem Std.ExtTreeSet.min_insert_le_min.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} {he : t ≠ ∅} :
  (cmp ((t.insert k).min ⋯) (t.min he)).isLE = true

theorem Std.ExtTreeSet.contains_diff.{u} {α : Type u} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} :
  (t₁ \ t₂).contains k = (t₁.contains k && !t₂.contains k)

theorem Std.ExtTreeSet.get_union_of_not_mem_right.{u} {α : Type u} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} (not_mem : k ∉ t₂) {h' : k ∈ t₁ ∪ t₂} :
  (t₁ ∪ t₂).get k h' = t₁.get k ⋯

theorem Std.ExtTreeSet.get?_eq_some_get!.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] [Inhabited α] {a : α} :
  a ∈ t → t.get? a = some (t.get! a)

theorem Std.ExtTreeSet.getD_eq_fallback_of_contains_eq_false.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {a fallback : α} :
  t.contains a = false → t.getD a fallback = fallback

theorem Std.ExtTreeSet.max?_erase_eq_of_not_compare_eq_max?.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α}
  (hc : ∀ {km : α}, t.max? = some km → ¬cmp k km = Ordering.eq) : (t.erase k).max? = t.max?

theorem Std.ExtTreeSet.min?_eq_some_iff_mem_and_forall.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {km : α} :
  t.min? = some km ↔ km ∈ t ∧ ∀ k ∈ t, (cmp km k).isLE = true

theorem Std.ExtTreeSet.get?_ofList_of_contains_eq_false.{u} {α : Type u} {cmp : α → α → Ordering}
  [Std.TransCmp cmp] [BEq α] [Std.LawfulBEqCmp cmp] {l : List α} {k : α}
  (contains_eq_false : l.contains k = false) : (Std.ExtTreeSet.ofList l cmp).get? k = none

theorem Std.ExtTreeSet.ext_contains.{u} {α : Type u} {cmp : α → α → Ordering} [Std.TransCmp cmp]
  [Std.LawfulEqCmp cmp] {t₁ t₂ : Std.ExtTreeSet α cmp}
  (h : ∀ (k : α), t₁.contains k = t₂.contains k) : t₁ = t₂

theorem Std.ExtTreeSet.le_maxD_of_contains.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} (hc : t.contains k = true) {fallback : α} :
  (cmp k (t.maxD fallback)).isLE = true

theorem Std.ExtTreeSet.get?_inter_of_mem_right.{u} {α : Type u} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k : α} (mem : k ∈ t₂) :
  (t₁ ∩ t₂).get? k = t₁.get? k

theorem Std.ExtTreeSet.min_insert.{u} {α : Type u} {cmp : α → α → Ordering} {t : Std.ExtTreeSet α cmp}
  [Std.TransCmp cmp] {k : α} :
  (t.insert k).min ⋯ = t.min?.elim k fun k' => if cmp k k' = Ordering.lt then k else k'

theorem Std.ExtTreeSet.max?_eq_some_maxD.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] (he : t ≠ ∅) {fallback : α} :
  t.max? = some (t.maxD fallback)

theorem Std.ExtTreeSet.min?_le_of_contains.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.ExtTreeSet α cmp} [Std.TransCmp cmp] {k km : α} (hc : t.contains k = true)
  (hkm : t.min?.get ⋯ = km) : (cmp km k).isLE = true

theorem Std.ExtTreeSet.min?_insert.{u} {α : Type u} {cmp : α → α → Ordering} {t : Std.ExtTreeSet α cmp}
  [Std.TransCmp cmp] {k : α} :
  (t.insert k).min? = some (t.min?.elim k fun k' => if cmp k k' = Ordering.lt then k else k')
